export interface ConnectorConfig {
  /** HubSpot private app access token. */
  HUBSPOT_ACCESS_TOKEN: string
  /** Injected fetch for testing. */
  fetch?: typeof fetch
}

export interface StripeCheckoutSessionCompleted {
  id: string
  object: 'checkout.session'
  customer_email: string
  client_reference_id?: string
  payment_status: string
  status: string
  [key: string]: unknown
}

export interface HubSpotContactResult {
  vid: number
  isNew: boolean
  hubspotContactEmail: string
  stripeSessionId: string
}

export async function handle(
  payload: StripeCheckoutSessionCompleted,
  config: ConnectorConfig
): Promise<HubSpotContactResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.customer_email) {
    throw new Error('Missing required field: customer_email')
  }
  if (!payload.id) {
    throw new Error('Missing required field: id')
  }

  const email = payload.customer_email
  const url = `https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/${encodeURIComponent(email)}`

  const body = {
    properties: [
      { property: 'email', value: email },
      ...(payload.client_reference_id
        ? [{ property: 'client_reference_id', value: payload.client_reference_id }]
        : []),
    ],
  }

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.HUBSPOT_ACCESS_TOKEN}`,
      'Content-Type': 'application/json',
      'Idempotency-Key': payload.id,
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} for ${url}`)
  }

  const data = (await response.json()) as { vid: number; isNew: boolean }

  return {
    vid: data.vid,
    isNew: data.isNew,
    hubspotContactEmail: email,
    stripeSessionId: payload.id,
  }
}

import { describe, it, expect, vi } from 'vitest'
