  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      HUBSPOT_ACCESS_TOKEN: 'test-token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeCheckoutSessionCompleted, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.vid).toBe(3234574)
    expect(result.isNew).toBe(false)
    expect(result.hubspotContactEmail).toBe('customer@example.com')
    expect(result.stripeSessionId).toBe(SOURCE_EXAMPLE.id)
  })
})

describe('handle', () => {
  it('maps fields correctly and sends Idempotency-Key', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/customer%40example.com')
      expect(req.headers.get('authorization')).toBe('Bearer test-token')
      expect(req.headers.get('idempotency-key')).toBe('cs_test_123')
      const body = req.json as { properties: Array<{ property: string; value: string }> }
      expect(body.properties).toEqual([
        { property: 'email', value: 'customer@example.com' },
        { property: 'client_reference_id', value: 'order_123' },
      ])
      return jsonResponse({ vid: 999, isNew: true })
    })

    const payload: StripeCheckoutSessionCompleted = {
      id: 'cs_test_123',
      object: 'checkout.session',
      customer_email: 'customer@example.com',
      client_reference_id: 'order_123',
      payment_status: 'paid',
      status: 'complete',
    }

    const result = await handle(payload, { HUBSPOT_ACCESS_TOKEN: 'test-token', fetch })
    expect(result.vid).toBe(999)
    expect(result.isNew).toBe(true)
    expect(calls.length).toBe(1)
  })

  it('omits client_reference_id when not present', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const body = req.json as { properties: Array<{ property: string; value: string }> }
      expect(body.properties).toEqual([{ property: 'email', value: 'customer@example.com' }])
      return jsonResponse({ vid: 888, isNew: false })
    })

    const payload: StripeCheckoutSessionCompleted = {
      id: 'cs_test_456',
      object: 'checkout.session',
      customer_email: 'customer@example.com',
      payment_status: 'paid',
      status: 'complete',
    }

    const result = await handle(payload, { HUBSPOT_ACCESS_TOKEN: 'test-token', fetch })
    expect(result.vid).toBe(888)
    expect(calls.length).toBe(1)
  })

  it('throws when customer_email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      id: 'cs_test_789',
      object: 'checkout.session' as const,
      payment_status: 'paid',
      status: 'complete',
    } as unknown as StripeCheckoutSessionCompleted

    await expect(handle(payload, { HUBSPOT_ACCESS_TOKEN: 'test-token', fetch })).rejects.toThrow(
      'Missing required field: customer_email'
    )
  })

  it('throws when id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      object: 'checkout.session' as const,
      customer_email: 'customer@example.com',
      payment_status: 'paid',
      status: 'complete',
    } as unknown as StripeCheckoutSessionCompleted

    await expect(handle(payload, { HUBSPOT_ACCESS_TOKEN: 'test-token', fetch })).rejects.toThrow(
      'Missing required field: id'
    )
  })

  it('throws on non-2xx response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ message: 'Unauthorized' }, 401))

    const payload: StripeCheckoutSessionCompleted = {
      id: 'cs_test_999',
      object: 'checkout.session',
      customer_email: 'customer@example.com',
      payment_status: 'paid',
      status: 'complete',
    }

    await expect(handle(payload, { HUBSPOT_ACCESS_TOKEN: 'test-token', fetch })).rejects.toThrow(
      'HubSpot API error: 401 Unauthorized for https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/customer%40example.com'
    )
    expect(calls.length).toBe(1)
  })

  it('uses injected fetch over global fetch', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ vid: 777, isNew: true }))
    const payload: StripeCheckoutSessionCompleted = {
      id: 'cs_test_injected',
      object: 'checkout.session',
      customer_email: 'injected@example.com',
      payment_status: 'paid',
      status: 'complete',
    }

    const result = await handle(payload, { HUBSPOT_ACCESS_TOKEN: 'test-token', fetch })
    expect(result.vid).toBe(777)
    expect(calls.length).toBe(1)
  })
})

